      "New · read with AI", "Upload your bank statement. The rest happens by itself.", "Drop in a screenshot or PDF from your bank. The AI reads every payment and picks the category you chose last time. You check it and tap Add.", "Handled safely", "Your file isn't kept and isn't used to train AI. Nothing is booked until you've checked it.", "No double bookings", "What's already in your books and transfers to your savings stay out, including fixed costs you booked ahead.", "Your payslip and mortgage too", "Gross, net and wage tax from your payslip and every loan part of your mortgage, filled in at once.", "A bank statement being read", "Read bank screenshots", "Reading the figures…", "Tick all", "3 of 5", "To savings account", "Transport", "Subscriptions", "Savings", "Car", "As last time", "Own transfer", "Already booked", "Add 3", "Example with demo data.",
      /*128*/ "Your runway", "How long could you last without income?", "Your runway is the number of months what's in your accounts would cover your fixed costs and budgets. The dashboard keeps it live and shows what you still need for a healthy buffer.", "Your buffer in one number", "No vague rule of thumb: your own balance divided by what a month really costs you.", "See when it would run out", "Month by month you see your money shrink if nothing came in any more.", "A goal you'll reach", "Pick 3 to 12 months. The app works out how much more you need and how long that takes to save.", "months", "Try it with your own numbers", "In your accounts", "Needed per month", "Goal: 6 months", "{n} of 6 months", "Past the minimum of 3 months", "Below the minimum of 3 months", "Goal reached", "in your accounts", "a month of fixed costs and budgets", "Without income the money would run out in {m}. For 6 months you need {a} more.", "Your goal of 6 months is reached: a healthy buffer.", "Your runway: how long your money covers your fixed costs without income",
      /*151*/ "Live demo", "Try it free now!", "7 days free · then cancel whenever you like", "Pays for itself", "The app pays for itself.", "Premium costs less than one forgotten subscription. What the app helps you find usually covers it in the first month.", "Premium per month", "A forgotten subscription cancelled", "Your insurance compared before the cancel-by date", "Your budget adjusted halfway through the month", "Saved per month", "Example: what people often find. You'll see your own amounts in your dashboard.", "Ready to see it for yourself?", "or look at the live demo first", "{n}× paid back",
