      /*faq*/ "Questions",
      "Frequently asked questions",
      "What does it cost?",
      "Try Premium free for 7 days. Then choose monthly, yearly or two years; at checkout you see the price in your own currency. Cancel any time.",
      "How do I cancel?",
      "In the app under Settings › Personal Finance Premium › Manage subscription. You keep Premium until the end of your period; nothing is charged after that.",
      "Do I have to connect my bank?",
      "No. You enter things yourself, or let AI read your bank statement or screenshots. There is no connection to your bank.",
      "Who can see my data?",
      "Your data is stored in the EU and never sold or used for ads. With an extra passphrase everything is encrypted in your browser, so even we can't read it.",
      "Is this financial advice?",
      "No. The app shows your own numbers and does the maths; the choices are yours.",
      "Does it work on my phone?",
      "Yes, in the browser on your phone, tablet and computer, with the same numbers everywhere. Apps for iPhone, iPad, Mac and Android are on the way.",
