      "Zuhause",
      "Schulden",
      "Eigenkapital",
      "Ziehen zum Drehen · auf einen Planeten zeigen",
      "Was du besitzt minus was du schuldest. Das gehört wirklich dir.",
      "Zieht nach innen: alles, was du im Zeitraum verdienst.",
      "Drückt nach außen: Fixkosten und Ausgaben im Zeitraum.",
      "Zieht nach innen: Jede Tilgung macht deine Schulden kleiner.",
      "Deine Anlagen. Die Börse bewegt sie, ohne dass du etwas tust.",
      "Der Wert deines Zuhauses, meist der größte Teil deines Besitzes.",
      "Drückt nach außen: deine Hypothek und andere Kredite.",
      "{n} Monate",
      "Eigenkapital nach {n} Monaten: {a} ({b})",
      "Dein Vermögen",
      "Dein Eigenkapital als Sonne, mit Einkommen, Ausgaben, Tilgung, Anlagen, Zuhause und Schulden als Planeten",
      "Das Geldmodell im Dashboard: Sieh, wie Einkommen, Ausgaben, Tilgung, Börse und Immobilienmarkt dein Eigenkapital bewegen, als Geldfluss, Vermögensgebäude oder Sonnensystem. Auf der Startseite: dein Vermögen als Sonnensystem.",
      "Geldmodell › Rückblick: sieh, was wirklich passiert ist, dieses Jahr bisher, je früherem Jahr oder alles seit deinem ersten Jahr: deine Bilanz damals und heute und woher der Unterschied kam.",
      "Geldmodell: jede Schuld als eigener Balken (Hypothek, Autokredit, Studienkredit…), und die Tilgung macht deine Hypothek sichtbar kleiner. Fixkosten folgen derselben Prognose wie Ausgaben.",
      "Geldmodell › Zeitmaschine: dein Eigenkapital als Turm pro Jahr, aufgebaut aus seiner Herkunft (Arbeit, Tilgung, Börse, Immobilienmarkt), mit deinen Schulden als Keller. Drück auf Abspielen und sieh dein Vermögen über die Jahre wachsen.",
      "Zeitmaschine: Blick fünf Jahre voraus mit gläsernen Türmen (Börse und Immobilienmarkt selbst einstellen), wechsle zwischen Herkunft und Besitz und Schulden (deine Schulden innerhalb deines Hauses) und sieh das Jahr, in dem du dein Haus gekauft hast.",
      "Ein Vorschuss bekommt das Datum, an dem du ihn zurück erwartest; ab drei Tagen vorher erinnert dich das Dashboard.",
      "Schnell hinzufügen zeigt, wie viele Arbeitsstunden eine Ausgabe kostet.",
      "Die App öffnet sich gleich mit den richtigen Zahlen: Nichts springt mehr, wenn die Kurse hereinkommen.",
      "Stellst du das Dashboard auf Jahr, zeigt die Liquiditätskachel dein Jahr: vom 1. Januar bis jetzt und was du Ende Dezember erwartest. Der Wechsel zum Geldmodell gleitet.",
      "Buche etwas auf dem iPad",
      "Schau aufs iPad: alles bewegt sich mit.",
      "Als Einnahme gebucht — schau aufs iPad.",
      "Als Ausgabe gebucht — schau aufs iPad.",
      "+ Einnahme",
      "− Ausgabe",
      "Betrag",
      "Tippe im Sonnensystem auf einen Planeten: Er öffnet sich in Schichten und zeigt, woraus er besteht, etwa deine Ausgaben je Kategorie oder jede Anlage.",
      "Auf der Startseite buchst du eine Einnahme oder Ausgabe auf dem iPad und siehst die App sofort mitgehen.",
      "Diesen Monat bereits gebuchte Fixkosten zählen wie gebucht; nur noch nicht gebuchte rechnen mit dem Durchschnitt. Die Liste beim Check-in scrollt jetzt.",
      "Auf der Startseite wird die Live-Karte neben dem iPad auf niedrigen Bildschirmen nicht mehr abgeschnitten.",
      "von {a} diesen Monat",
      "Der Lohnzähler auf der Startseite zeigt, auf welchen Monatsbetrag er zählt: So siehst du, dass es dein Monat bis jetzt ist.",
      "Auf der Startseite ist das iPad auf jedem Bildschirm vollständig zu sehen.",
      "pro Monat",
      "Tippen, um deinen eigenen Betrag einzugeben",
      "Auf der Startseite sind Gehalt, Anlagen und Zuhause oben deine eigenen Beträge: antippen, eintragen, und alles darunter rechnet mit.",
      "Was du oben auf der Startseite als Gehalt, Anlagen und Zuhause einträgst, verändert jetzt auch die App auf dem iPad daneben.",
      "Anlagen: Ergebnis und Prozentsatz sind wieder getrennt, und auf dem Handy zeigt das Diagramm wieder seine Punkte.",
      "Liquidität und Eigenkapital zeigen jetzt auch, um wie viel Prozent sie gewachsen sind: heute, diesen Monat, dieses Jahr und seit Januar.",
      "Zeitmaschine: Nur das Jahr, das du ansiehst, sagt noch „erwartet“, und die Jahreszahlen über den Türmen überlappen nicht mehr.",
      "Bei der Anmeldung steht jetzt, dass du dich mit demselben Konto auch in der App auf iPhone, iPad und Mac anmeldest.",
      "Das iPad oben auf der Startseite zeigt die App jetzt von selbst: Alle paar Sekunden wechselt es zum nächsten Tab.",
