      "Chaque amélioration de Personal Finance, avec la date de sa mise en ligne.",
      "Nouveau",
      "Amélioré",
      "Retour à l'accueil",
      "Cette page des nouveautés : vois ce qui est nouveau, date par date.",
      "La démo n'a plus de limite de temps. Explore aussi longtemps que tu veux.",
      "Sur la page d'accueil, le côté montre où tu es et ce qui reste à voir.",
      "Essaie Premium gratuitement pendant 7 jours, directement depuis la page d'accueil.",
      "Les animations et l'arrière-plan animé se règlent dans les Réglages ; la barre latérale est plus calme.",
      "À la configuration : ton logement (location ou propriété, prêt immobilier) et ton relevé bancaire, lus par l'IA.",
      "Liquidités : par mois et par jour, tu vois exactement où va ton argent.",
