      "Conditions d’utilisation et une politique de confidentialité renouvelée, en bas de chaque page.",
      "Compléter les mois précédents : choisis un mois jusqu’à janvier et remplis-le avec ton relevé bancaire, des totaux rapides ou une estimation.",
      "L’anneau du milieu devient « Sous ton revenu » : un jour compte quand tes dépenses restent sous le revenu de ce jour.",
      /*live 17 Nov*/ "Tout le monde peut désormais créer un compte et essayer Premium gratuitement pendant 7 jours.",
      "Des prix dans ta devise : en dollars aux États-Unis, en livres au Royaume-Uni.",
      /*faq*/ "Questions",
      "Questions fréquentes",
      "Combien ça coûte ?",
      "Essaie Premium gratuitement pendant 7 jours. Ensuite, choisis au mois, à l'année ou pour deux ans ; au paiement, tu vois le prix dans ta devise. Résiliable à tout moment.",
      "Comment résilier ?",
      "Dans l'app, sous Réglages › Personal Finance Premium › Gérer l'abonnement. Tu gardes Premium jusqu'à la fin de ta période ; ensuite, plus rien n'est prélevé.",
      "Dois-je connecter ma banque ?",
      "Non. Tu saisis toi-même, ou tu laisses l'IA lire ton relevé ou tes captures d'écran. Il n'y a aucune connexion à ta banque.",
      "Qui peut voir mes données ?",
      "Tes données sont stockées dans l'UE et ne sont jamais vendues ni utilisées pour la publicité. Avec une phrase secrète en plus, tout est chiffré dans ton navigateur, si bien que même nous ne pouvons pas le lire.",
      "Est-ce du conseil financier ?",
      "Non. L'app montre tes propres chiffres et fait les calculs ; les choix t'appartiennent.",
      "Ça marche sur mon téléphone ?",
      "Oui, dans le navigateur de ton téléphone, ta tablette et ton ordinateur, avec partout les mêmes chiffres. Des apps pour iPhone, iPad, Mac et Android arrivent.",
      "Puis-je emporter ou supprimer mes données ?",
      "Oui. Dans Réglages › Tes données, tu télécharges tout dans un fichier, ou tu supprimes ton compte avec tout son contenu.",
      /*live 18 Nov*/ "Télécharge toutes tes données dans un fichier, ou supprime ton compte avec tout son contenu (Réglages › Tes données).",
      "Questions fréquentes sur la page d'accueil.",
      "Votre mois sur papier.",
