      "Un rapport mensuel en PDF, avec des données de démo",
      "Téléchargez votre mois et votre année dans un beau rapport PDF, avec les chiffres pour votre déclaration d'impôts (Premium).",
      "Sur la page d'accueil : votre mois sur papier.",
      "Le rapport annuel affiche le mois en cours en direct et les mois à venir en prévision.",
      "Votre horloge de l'argent",
      "Votre salaire, c'est votre journée de 24 heures.",
      "Placez votre salaire net sur une horloge de 24 heures. Vos plus grosses dépenses passent en premier, et le temps qui reste est à vous. D'un coup d'œil, vous voyez combien d'heures de votre journée vous travaillez pour votre logement.",
