      "Nuevo · lectura con IA", "Sube tu extracto bancario. El resto va solo.", "Arrastra una captura o un PDF de tu banco. La IA lee cada pago y elige la categoría que elegiste la última vez. Tú lo revisas y tocas Añadir.", "Procesado con seguridad", "Tu archivo no se guarda ni se usa para entrenar IA. No se registra nada hasta que lo revises.", "Sin movimientos duplicados", "Lo que ya está registrado y las transferencias a tu ahorro se quedan fuera, también los gastos fijos registrados por adelantado.", "También tu nómina y tu hipoteca", "Bruto, neto y retención de tu nómina, y cada tramo de tu hipoteca, rellenados de una vez.", "Se está leyendo un extracto bancario", "Leer capturas del banco", "Leyendo las cifras…", "Marcar todo", "3 de 5", "A la cuenta de ahorro", "Transporte", "Suscripciones", "Ahorro", "Coche", "Como la última vez", "Transferencia propia", "Ya registrado", "Añadir 3", "Ejemplo con datos de demostración.",
      /*128*/ "Tu autonomía", "¿Cuánto aguantarías sin ingresos?", "Tu autonomía es el número de meses que lo que tienes en tus cuentas cubre tus gastos fijos y presupuestos. El panel la sigue en directo y muestra lo que te falta para un colchón sano.", "Tu colchón en una cifra", "Nada de reglas vagas: tu propio saldo dividido entre lo que de verdad te cuesta un mes.", "Mira cuándo se acabaría", "Mes a mes ves cómo se reduce tu dinero si ya no entrara nada.", "Un objetivo que alcanzas", "Elige de 3 a 12 meses. La app calcula cuánto te falta y cuánto tardas en ahorrarlo.", "meses", "Pruébalo con tus propias cifras", "En tus cuentas", "Necesario al mes", "Objetivo: 6 meses", "{n} de 6 meses", "Por encima del mínimo de 3 meses", "Por debajo del mínimo de 3 meses", "Objetivo alcanzado", "en tus cuentas", "al mes en gastos fijos y presupuestos", "Sin ingresos, el dinero se acabaría en {m}. Para 6 meses te faltan {a}.", "Tu objetivo de 6 meses está alcanzado: un colchón sano.", "Tu autonomía: cuánto tiempo cubre tu dinero tus gastos fijos sin ingresos",
      /*151*/ "Demo en vivo", "¡Pruébalo gratis ahora!", "7 días gratis · después cancela cuando quieras", "Se paga sola", "La app se paga sola.", "Premium cuesta menos que una suscripción olvidada. Lo que la app te ayuda a recuperar suele cubrirlo ya en el primer mes.", "Premium al mes", "Una suscripción olvidada cancelada", "Tu seguro comparado antes de la fecha de cancelación", "Tu presupuesto ajustado a mitad de mes", "Ahorrado al mes", "Ejemplo: lo que la gente suele recuperar. Tus propias cifras las ves en tu panel.", "¿Listo para verlo por ti mismo?", "o mira primero la demo en vivo", "Recuperado {n}×",
