      "No. Lo introduces tú, o dejas que la IA lea tu extracto o tus capturas. No hay ninguna conexión con tu banco.",
      "¿Quién puede ver mis datos?",
      "Tus datos se guardan en la UE y nunca se venden ni se usan para publicidad. Con una frase de contraseña extra, todo se cifra en tu navegador, así que ni nosotros podemos leerlo.",
