      "Sono {a} al giorno, {b} all'ora e {c} al secondo. Oggi sei già a {d}.",
      "Nuovo · lettura con IA", "Carica il tuo estratto conto. Il resto va da sé.", "Trascina uno screenshot o un PDF della tua banca. L'IA legge ogni pagamento e sceglie la categoria che hai scelto l'ultima volta. Tu controlli e tocchi Aggiungi.", "Gestito in sicurezza", "Il file non viene conservato né usato per addestrare l'IA. Nulla viene registrato prima che tu l'abbia controllato.", "Nessun doppione", "Ciò che è già registrato e i giroconti verso i risparmi restano fuori, anche le spese fisse registrate in anticipo.", "Anche busta paga e mutuo", "Lordo, netto e ritenute della busta paga e ogni quota del mutuo, compilati in una volta.", "Lettura di un estratto conto", "Leggi screenshot bancari", "Lettura delle cifre…", "Seleziona tutto", "3 di 5", "Al conto risparmio", "Trasporti", "Abbonamenti", "Risparmio", "Auto", "Come l'ultima volta", "Giroconto", "Già registrato", "Aggiungi 3", "Esempio con dati demo.",
      /*128*/ "La tua autonomia", "Quanto resisteresti senza entrate?", "La tua autonomia è il numero di mesi in cui i soldi sui tuoi conti coprono spese fisse e budget. La dashboard la tiene aggiornata in diretta e mostra quanto ti manca per un cuscinetto sano.", "Il tuo cuscinetto in un numero", "Niente regole vaghe: il tuo saldo diviso per quanto ti costa davvero un mese.", "Guarda quando finirebbero", "Mese dopo mese vedi i tuoi soldi calare se non entrasse più nulla.", "Un obiettivo che raggiungi", "Scegli da 3 a 12 mesi. L'app calcola quanto ti manca e quanto ci vuole per risparmiarlo.", "mesi", "Prova con i tuoi numeri", "Sui tuoi conti", "Necessario al mese", "Obiettivo: 6 mesi", "{n} di 6 mesi", "Oltre il minimo di 3 mesi", "Sotto il minimo di 3 mesi", "Obiettivo raggiunto", "sui tuoi conti", "al mese tra spese fisse e budget", "Senza entrate i soldi finirebbero a {m}. Per 6 mesi ti servono ancora {a}.", "Il tuo obiettivo di 6 mesi è raggiunto: un cuscinetto sano.", "La tua autonomia: per quanto i tuoi soldi coprono le spese fisse senza entrate",
      /*151*/ "Demo dal vivo", "Provalo gratis ora!", "7 giorni gratis · poi disdici quando vuoi", "Si ripaga da sola", "L'app si ripaga da sola.", "Premium costa meno di un abbonamento dimenticato. Quello che l'app ti aiuta a ritrovare di solito lo ripaga già nel primo mese.", "Premium al mese", "Un abbonamento dimenticato disdetto", "La tua assicurazione confrontata prima della data di disdetta", "Il tuo budget corretto a metà mese", "Risparmiato al mese", "Esempio: ciò che le persone ritrovano spesso. I tuoi importi li vedi nella tua dashboard.", "Pronto a vederlo con i tuoi occhi?", "oppure guarda prima la demo dal vivo", "Ripagato {n}×",
