      "Devo collegare la mia banca?",
      "No. Inserisci tu i dati, oppure lasci che l'IA legga il tuo estratto conto o i tuoi screenshot. Non c'è alcun collegamento con la tua banca.",
      "Chi può vedere i miei dati?",
      "I tuoi dati sono conservati nell'UE e non vengono mai venduti né usati per la pubblicità. Con una passphrase in più, tutto viene cifrato nel tuo browser, così nemmeno noi possiamo leggerlo.",
