      "Thẻ Wrapped thật từ ứng dụng, với dữ liệu demo.",
      /*50*/ "01 Bảng cân đối", "Biết bạn thật sự đáng giá bao nhiêu",
      "Nhà, tiền tiết kiệm và khoản đầu tư đặt cạnh thế chấp và khoản vay: một con số trung thực, cập nhật mỗi ngày, như doanh nghiệp giữ bảng cân đối.",
      "02 Ngân sách", "Không bất ngờ cuối tháng",
      "Giữa tháng bạn đã thấy ngân sách nào sẽ không đủ, để còn điều chỉnh thay vì giật mình sau đó.",
