      "04 Đầu tư",
      /*60*/ "Mọi khoản đầu tư trong một cái nhìn",
      "Cổ phiếu, ETF, bitcoin và vàng cùng nhau, theo giá trực tiếp. Không cần mở năm ứng dụng để biết mình đang ở đâu.",
      "05 Tiến độ", "Một phút mỗi ngày giúp bạn luôn cập nhật",
      "Check-in chỉ hỏi mọi thứ có đúng không. Bạn nhận điểm, vòng và ngọn lửa, để ghi chép trở nên tự nhiên như đếm bước chân.",
      "Hoàn toàn theo bạn.", "Không có mẫu chuẩn. Chỉ vài phút là đời sống tài chính của bạn đã ở trong đó, đúng như thực tế.",
      "01 Lộ trình của bạn", "Nắm toàn cảnh trong hai phút",
      "Chọn bắt đầu nhanh và bảng điều khiển sẵn sàng ngay. Muốn đầy đủ? Dành mười phút: phần bỏ qua bây giờ, bạn bổ sung sau.",
      /*70*/ "02 Chi phí cố định", "Nhập một lần, sau đó tự chạy",
      "Tiền nhà, điện nước, bảo hiểm và gói đăng ký tự ghi sổ mỗi tháng đúng ngày. Bạn thấy những gì còn sắp trừ tháng này, và số dư đã tính trước.",
      "03 Gói đăng ký", "Xem gói đăng ký thật sự tốn bao nhiêu",
